	@Test
	void initialShellReturnsResolvedResourceAndNamespacesWithoutRows() throws Exception {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.setNamespace("ex", "urn:test:");
			connection.add(repository.getValueFactory().createIRI("urn:test:resource"),
					repository.getValueFactory().createIRI("urn:test:predicate"),
					repository.getValueFactory().createLiteral("x"));
		}
		List<JsonNode> records = execute(request("ex:resource"));
		assertThat(metadata(records).path("explore-resource").asText()).isEqualTo("<urn:test:resource>");
		assertThat(metadata(records).path("explore-graph-mode").asText()).isEqualTo("physical");
		assertThat(records).anyMatch(record -> "namespaces".equals(record.path("type").asText()));
		assertThat(records).anyMatch(record -> "links".equals(record.path("type").asText()));
		assertThat(rows(records)).isEmpty();
		assertThat(records.getLast().path("type").asText()).isEqualTo("end");
	}

	@Test
	void eachListingUsesItsOwnHardTierAndIgnoresLegacyPagingParameters() throws Exception {
		ValueFactory factory = repository.getValueFactory();
		IRI subject = factory.createIRI("urn:test:resource");
		IRI predicate = factory.createIRI("urn:test:predicate");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int i = 0; i < 10_001; i++) {
				connection.add(subject, predicate, factory.createLiteral("value-" + i));
			}
			connection.commit();
		}
		MockHttpServletRequest initial = section("outgoing", "rows");
		initial.addParameter("offset", "9999999");
		initial.addParameter("know_total", "9999999");
		initial.addParameter("limit_explore", "0");
		List<JsonNode> first = execute(initial);
		assertThat(metadata(first).path("explore-limit").asInt()).isEqualTo(10_000);
		assertThat(rows(first)).hasSize(10_000);
		assertThat(first.getLast().path("type").asText()).isEqualTo("end");

		MockHttpServletRequest more = section("outgoing", "rows");
		more.addParameter("load", "more");
		List<JsonNode> expanded = execute(more);
		assertThat(metadata(expanded).path("explore-limit").asInt()).isEqualTo(1_000_000);
		assertThat(rows(expanded)).hasSize(10_001);
		assertThat(expanded.getLast().path("type").asText()).isEqualTo("end");
	}

	@Test
	void blankNodeReferencesRetainStoredIdentity() throws Exception {
		ValueFactory factory = repository.getValueFactory();
		BNode blank = factory.createBNode("space >雪");
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(blank, factory.createIRI("urn:test:predicate"), factory.createLiteral("value"));
		}
		MockHttpServletRequest request = section("outgoing", "rows");
		request.setParameter("resource", BlankNodeReferences.toReference(blank.getID()));
		List<JsonNode> answer = execute(request);
		assertThat(rows(answer)).singleElement().satisfies(row -> {
			assertThat(row.get(0).path("kind").asText()).isEqualTo("bnode");
			assertThat(row.get(0).path("value").asText()).isEqualTo(blank.getID());
			assertThat(row.get(0).path("reference").asBoolean()).isTrue();
		});
	}

